"use strict";
const systemJavaTools=[{id:'calculator',title:'掌上计算器'},{id:'notes',title:'随手记'},{id:'snake',title:'经典贪吃蛇'}];
const systemApps=[
 {id:'browser',name:'UC 浏览器',icon:'UC',color:'orange',desc:'经典橙色导航 · 站内网页',core:true},
 {id:'store',name:'应用下载',icon:'↓',color:'green',desc:'装一点好用的小软件',core:true},
 {id:'sms',name:'短信',icon:'✉',color:'lime',desc:'本机短信体验',core:true},
 {id:'books',name:'掌上书房',icon:'书',color:'brown',desc:'公版小说与原创短篇'},
 {id:'games',name:'游戏厅',icon:'✣',color:'purple',desc:'Java 游戏与像素小游戏'},
 {id:'music',name:'音乐随身听',icon:'♫',color:'pink',desc:'原创配乐与播放列表'},
 {id:'calculator',name:'计算器',icon:'＋',color:'blue',desc:'可运行的 Java ME 计算器',jar:'calculator'},
 {id:'notes',name:'随手记',icon:'▤',color:'yellow',desc:'Java ME 便笺 · 本机保存',jar:'notes'},
 {id:'snake',name:'贪吃蛇',icon:'▦',color:'lime',desc:'可运行的 Java ME 贪吃蛇',jar:'snake'},
 {id:'photos',name:'主题壁纸',icon:'▧',color:'blue',desc:'换一张桌面背景'},
 {id:'gallery',name:'图文馆',icon:'图',color:'pink',desc:'翻翻那时的故事'},
 {id:'news',name:'新闻',icon:'报',color:'blue',desc:'跟着年代读历史'},
 {id:'videos',name:'掌上影院',icon:'▶',color:'purple',desc:'开放授权影像'},
 {id:'magazines',name:'报刊亭',icon:'刊',color:'brown',desc:'旧杂志与原创连载'}
];
let systemInstalled=['browser','store','sms','books','games','music'];
try{const saved=JSON.parse(localStorage.getItem('olddays-system-apps')||'null');if(Array.isArray(saved))systemInstalled=[...new Set(['browser','store','sms',...saved.filter(id=>systemApps.some(a=>a.id===id))])];}catch{}
let ucPage='home',ucQuery='',ucContent='',systemHomeIndex=0;
function installedSystemApps(){return systemApps.filter(a=>systemInstalled.includes(a.id));}
function moveSystemSelection(dir){const apps=installedSystemApps();systemHomeIndex=Math.max(0,Math.min(apps.length-1,systemHomeIndex+({up:-4,down:4,left:-1,right:1}[dir]||0)));document.querySelectorAll('.phone-home-grid .system-app').forEach((b,i)=>{b.classList.toggle('system-selected',i===systemHomeIndex);if(i===systemHomeIndex)b.scrollIntoView?.({block:'nearest'});});}
function launchSystemNumber(key){const a=installedSystemApps()[Number(key)-1];if(a)launchSystemApp(a.id);}
function systemIcon(a,extra=''){return `<button class="system-app ${extra}" data-system-launch="${a.id}"><b class="system-icon tone-${a.color}">${a.icon}</b><span>${a.name}</span></button>`;}
function renderSystemHome(){return `<section class="system-home"><div class="system-platform"><span>▂▄▆　中国移动</span><span>旧日 S60　▰</span></div><header class="system-clock"><small>OLDDAYS / 旧日应用平台</small><h1>20:04</h1><p>${escapeHTML(date.replaceAll('-',' / '))}　掌上时光</p></header><div class="system-widget"><div><b>欢迎回到掌上时代</b><span>装应用、看小说，或者再玩一局。</span></div><button data-phone-lab>选择我的手机 ›</button></div><div class="system-apps" aria-label="已安装应用">${systemApps.filter(a=>systemInstalled.includes(a.id)&&!['browser','store','sms'].includes(a.id)).map(a=>systemIcon(a)).join('')}<button class="system-app" data-system-launch="store"><b class="system-icon system-add">＋</b><span>添加应用</span></button></div><div class="system-page-dots">● ○ ○</div><nav class="system-dock" aria-label="桌面快捷应用">${['browser','sms','store'].map(id=>systemIcon(systemApps.find(a=>a.id===id))).join('')}<button class="system-app" data-action="settings"><b class="system-icon tone-blue">⚙</b><span>设置</span></button></nav><footer>旧日 S60 · 网页重制桌面 <button data-system-portal>旧日导航 ›</button></footer></section>`;}
function phoneStoreMarkup(){return `<section class="phone-app-store"><header><small>OLDDAYS DOWNLOAD</small><h2>应用下载</h2><p>给小小的手机，装一个新世界。</p></header><div class="store-section-label">推荐应用 · ${systemInstalled.length} 个已安装</div>${systemApps.filter(a=>!a.core).map(a=>`<article class="store-app"><b class="system-icon tone-${a.color}">${a.icon}</b><div><h3>${a.name}</h3><p>${a.desc}</p>${a.jar?`<a href="javame/demos/${a.jar}.jar" download>下载 .jar 文件</a>`:'<small>本站网页应用</small>'}</div><button ${systemInstalled.includes(a.id)?`data-system-launch="${a.id}"`:`data-system-install="${a.id}"`}>${systemInstalled.includes(a.id)?'打开':'安装'}</button></article>`).join('')}<p class="store-footnote">安装后会保存在本站桌面。JAR 文件可另存；UC 为怀旧界面重制，非官方安装包。</p></section>`;}
function ucRenderedContent(){const previous=phoneState.app;try{phoneState.app=ucContent;return phoneScreen();}finally{phoneState.app=previous;}}
function phoneUCMarkup(){const links=[['news','新闻'],['books','小说'],['games','游戏'],['music','音乐'],['videos','视频'],['magazines','报刊'],['gallery','图文'],['store','软件下载']];const results=links.filter(([,title])=>!ucQuery||title.includes(ucQuery));return `<section class="phone-uc"><header class="uc-top"><b>UC</b><span>优视浏览器<small>轻快上网 · 旧日重制</small></span><button data-phone-app="home" aria-label="退出UC回到手机桌面">⌂</button></header><form data-uc-search class="uc-address"><span>⌕</span><input name="query" aria-label="UC搜索站内内容" placeholder="搜索站内内容" value="${escapeHTML(ucQuery)}"><button>搜索</button></form><nav class="uc-tabs">${[['home','首页'],['nav','网址导航'],['saved','书签']].map(([id,title])=>`<button data-uc-tab="${id}" aria-pressed="${ucPage===id}">${title}</button>`).join('')}</nav>${ucContent?`<div class="uc-heading"><button data-uc-back>‹ 返回导航</button><span>${links.find(x=>x[0]===ucContent)?.[1]||'软件下载'}</span></div><div class="uc-site-content">${ucRenderedContent()}</div>`:ucPage==='saved'?'<div class="uc-heading">我的书签</div><button class="uc-bookmark" data-uc-open="books">☆ 掌上书房</button><button class="uc-bookmark" data-uc-open="news">☆ 年代新闻</button>':`<div class="uc-quick-links">${results.map(([id,title])=>`<button data-uc-open="${id}">${title}</button>`).join('')||'<p>没有找到，试试“小说”或“新闻”。</p>'}</div><div class="uc-heading">${ucQuery?'搜索结果':ucPage==='nav'?'常用网址 · 本站怀旧页':'热点资讯'}<small>${year()} 年</small></div>${!ucQuery&&ucPage==='home'?`<div class="uc-news">${(yearEvents[year()]||[]).slice(0,5).map((r,i)=>`<button data-uc-news="${i}"><span>新闻</span>${escapeHTML(r[1])}</button>`).join('')}</div><div class="uc-heading">下载推荐</div><div class="uc-download"><b class="system-icon tone-green">↓</b><span>掌上应用中心<small>计算器 · 随手记 · Java小游戏</small></span><button data-uc-open="store">进入</button></div>`:''}`}<footer class="uc-bottom"><button data-uc-back>‹ 后退</button><button data-uc-tab="home">⌂ 首页</button><button data-uc-tab="nav">☷ 导航</button><button data-uc-tab="saved">☆ 书签</button></footer></section>`;}
function installSystemApp(id){if(!systemApps.some(a=>a.id===id)||systemInstalled.includes(id))return false;systemInstalled.push(id);try{localStorage.setItem('olddays-system-apps',JSON.stringify(systemInstalled));}catch{}return true;}
function launchSystemApp(id){const app=systemApps.find(a=>a.id===id);if(!app)return;if(app.jar){pocketJavaChoice=app.jar;openPhoneLab('java');}else openPhoneLab(id);if(!document.body.classList.contains('pocket-expanded'))pocketExpand();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-system-launch],[data-system-install],[data-system-portal],[data-uc-tab],[data-uc-news],[data-uc-open],[data-uc-back]');if(!b)return;e.preventDefault();if(b.dataset.systemLaunch)return launchSystemApp(b.dataset.systemLaunch);if(b.dataset.systemInstall){if(!installSystemApp(b.dataset.systemInstall))return;refreshPhone();toast('已安装到桌面');return;}if(b.hasAttribute('data-system-portal'))return navigate({type:'portal',name:'旧日导航',url:'archaeo://portal'});if(b.hasAttribute('data-uc-back')){if(phoneState.article!==null){phoneState.article=null;}else if(ucContent){ucContent='';}else return phoneSelectApp('home');return refreshPhone();}if(b.dataset.ucOpen){ucContent=b.dataset.ucOpen;phoneState.article=null;return refreshPhone();}if(b.dataset.ucTab){ucPage=b.dataset.ucTab;ucQuery='';ucContent='';return refreshPhone();}if(b.dataset.ucNews!==undefined){ucContent='news';phoneState.article=Number(b.dataset.ucNews);refreshPhone();}});
document.addEventListener('submit',e=>{if(!e.target.matches('[data-uc-search]'))return;e.preventDefault();ucQuery=String(new FormData(e.target).get('query')||'').trim().slice(0,80);ucPage='home';ucContent='';refreshPhone();});

function phoneUCKey(key){if(key==='0'){ucContent='';ucQuery='';ucPage='home';phoneState.article=null;return refreshPhone();}if(key==='#'){ucPage='nav';ucContent='';return refreshPhone();}const destinations=['news','books','games','music','videos','magazines','gallery','store'];if(/^[1-8]$/.test(key)){ucContent=destinations[Number(key)-1];phoneState.article=null;refreshPhone();}}
document.addEventListener('keydown',e=>{if(current.type!=='phone'||phoneState.app!=='browser'||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.repeat)return;if(/^[0-9#]$/.test(e.key)){e.preventDefault();phoneUCKey(e.key);}else if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();document.querySelector('#device-viewport').scrollBy({top:e.key==='ArrowUp'?-100:100,behavior:'smooth'});}});
